import React from 'react'

function Miniprofile() {
  return (
    <div>
        <h1>Instagram Mini Profile</h1>
 style={{
        width: '250px',
        padding: '20px',
        border: '1px solid #ddd',
        borderRadius: '10px',
        textAlign: 'center',
        margin: '20px auto',
        boxShadow: '0 2px 5px rgba(0,0,0,0.2)'
      }}
    
      <img
        src="data:image/jpeg;base64,"
        alt="Profile"
        style={{
          width: '100px',
          height: '100px',
          borderRadius: '50%'
        }}
      />

      <h2>Mamta Chavda</h2>

      <p> Learning React | Future Web Developer</p>
    </div>
  )
}

export default Miniprofile
